<script setup>
defineProps({ items: Array, selected: String, query: String, group: String, groups: Array, labels: Object, cycle: Function, random: Function });
defineEmits(['update:selected','update:query','update:group']);
</script>
<template><PanelFrame :title="`Визуализатор · ${items.length}`"><input type="search" :value="query" placeholder="Поиск: beyond, nebula, fluid…" @input="$emit('update:query',$event.target.value)" /><div class="flex flex-wrap gap-1.5"><button v-for="item in groups" :key="item.id" class="chip" :aria-pressed="group===item.id" @click="$emit('update:group',group===item.id?'':item.id)">{{ item.name }}</button></div><div class="plist" role="listbox"><button v-for="item in items" :key="item.id" class="pitem" role="option" :aria-current="selected===item.id" @click="$emit('update:selected',item.id)"><b /><span>{{item.name}}</span><em>{{labels[item.group]}}</em></button></div><div class="grid grid-cols-2 gap-2"><button class="btn" @click="cycle(-1)">← Пред</button><button class="btn" @click="cycle(1)">След →</button></div><button class="btn" @click="random">🎲 Случайный</button></PanelFrame></template>
